<script lang="ts">
  import{onMount}from'svelte';import Modal from'../components/Modal.svelte';import ModelTestPanel from'../components/ModelTestPanel.svelte';import{api}from'../lib/api';import{t}from'../lib/i18n.svelte';
  type ModelInfo={slug:string;display_name:string;description:string;identity:string;priority:number;context_window:number;input_modalities:string[];supported_reasoning_levels:string[]};type ModelEntry={upstream_model?:string;model_info?:ModelInfo};type Group={provider?:string;type?:string;tool_profile?:string;models?:Record<string,ModelEntry>;validation_error?:string};type Preset=ModelInfo;type Dict=Record<string,unknown>;type Config={providers?:Record<string,{enabled?:boolean}>;model_groups?:Record<string,Group>;models?:Record<string,unknown>;tool_profile_presets?:{id:string;name:string}[];model_presets?:Preset[];codex?:Dict;server?:Dict};type Row={id:number;name:string;upstream:string;info:ModelInfo|null};
  let config=$state<Config>({});let name=$state('');let originalName=$state('');let provider=$state('');let toolProfile=$state('');let rows=$state<Row[]>([]);let rowSequence=0;let discovered=$state<string[]>([]);let discoveryFilter=$state('');let selectedDiscovered=$state(new Set<string>());let prefix=$state('');let loading=$state(true);let busy=$state(false);let error=$state('');let notice=$state('');let groupOpen=$state(false);let fetchOpen=$state(false);let infoRowId=$state<number|null>(null);let infoDraft=$state<ModelInfo|null>(null);let providerFilter=$state('');let search=$state('');let collapsed=$state(new Set<string>());let reviewModel=$state('');let consolidationModel=$state('');let extractModel=$state('');
  let filteredDiscovered=$derived(discovered.filter((item)=>item.toLowerCase().includes(discoveryFilter.trim().toLowerCase())));let configuredModels=$derived(Object.keys(config.models??{}).sort());
  const message=(value:unknown)=>value instanceof Error?value.message:String(value);const copyInfo=(info:ModelInfo):ModelInfo=>JSON.parse(JSON.stringify(info))as ModelInfo;const blankInfo=(row:Row):ModelInfo=>({slug:row.upstream||row.name,display_name:row.name,description:'',identity:'',priority:1,context_window:128000,input_modalities:['text'],supported_reasoning_levels:['medium']});
  function presetFor(row:Row):Preset|undefined{const slug=row.upstream||row.name;return config.model_presets?.find((item)=>item.slug===slug);}function addRow(modelName='',entry:ModelEntry={}):void{rows=[...rows,{id:++rowSequence,name:modelName,upstream:entry.upstream_model??'',info:entry.model_info?copyInfo(entry.model_info):null}];}function closeInfo():void{infoRowId=null;infoDraft=null;}function removeRow(id:number):void{rows=rows.filter((row)=>row.id!==id);if(infoRowId===id)closeInfo();}function infoRow():Row|undefined{return rows.find((row)=>row.id===infoRowId);}function editInfo(row:Row):void{infoDraft=copyInfo(row.info??presetFor(row)??blankInfo(row));infoRowId=row.id;}function toggleList(field:'input_modalities'|'supported_reasoning_levels',value:string,checked:boolean):void{if(!infoDraft)return;const current=new Set(infoDraft[field]);checked?current.add(value):current.delete(value);infoDraft[field]=[...current];}
  function format(template:string,displayName:string):string{return template.replace('{display_name}',displayName);}function infoStatus(row:Row):{text:string;detected:boolean;modified:boolean}{const preset=presetFor(row);if(!preset)return{text:t('modelInfo.notDetected','No model preset detected. Please enter model information manually.'),detected:false,modified:false};const modified=!!row.info&&JSON.stringify(row.info)!==JSON.stringify(preset);return{text:format(t(modified?'modelInfo.detectedModified':'modelInfo.detected',modified?'Auto-detected: {display_name} (modified)':'Auto-detected: {display_name}'),preset.display_name),detected:true,modified};}
  function clearInfo():void{const row=infoRow();if(row){row.info=null;rows=[...rows];}closeInfo();}function applyInfo():void{const row=infoRow();if(!row||!infoDraft)return;const stringsReady=[infoDraft.slug,infoDraft.display_name,infoDraft.description,infoDraft.identity].every((value)=>value.trim());if(!stringsReady||!Number.isInteger(infoDraft.priority)||infoDraft.priority<=0||!Number.isInteger(infoDraft.context_window)||infoDraft.context_window<=0||!infoDraft.input_modalities.length||!infoDraft.supported_reasoning_levels.length){error=t('modelInfo.completeRequired','Complete every model information field before applying.');return;}row.info=copyInfo(infoDraft);rows=[...rows];closeInfo();}
  function hydrate(next:Config):void{config=next;if(!provider)provider=Object.keys(next.providers??{})[0]??'';const codex=next.codex??{};const memories=(codex.memories&&typeof codex.memories==='object'?codex.memories:{})as Dict;reviewModel=String(codex.auto_review_model_override??'');consolidationModel=String(memories.consolidation_model??'');extractModel=String(memories.extract_model??'');}
  async function load(signal?:AbortSignal):Promise<void>{try{hydrate(await api.get<Config>('/admin/api/config',signal));error='';}catch(cause){if(!(cause instanceof DOMException&&cause.name==='AbortError'))error=message(cause);}finally{loading=false;}}
  function reset():void{name='';originalName='';provider=Object.keys(config.providers??{})[0]??'';toolProfile='';rows=[];addRow();discovered=[];selectedDiscovered=new Set();discoveryFilter='';prefix='';closeInfo();error='';notice='';}
  function openNew():void{reset();groupOpen=true;}function edit(groupName:string,group:Group):void{name=groupName;originalName=groupName;provider=group.provider??'';toolProfile=group.tool_profile??'';rows=[];for(const[modelName,entry]of Object.entries(group.models??{}))addRow(modelName,entry);if(!rows.length)addRow();discovered=[];selectedDiscovered=new Set();closeInfo();error='';groupOpen=true;}
  function modelPayload():Record<string,ModelEntry>{const output:Record<string,ModelEntry>={};for(const row of rows){const exposed=row.name.trim();if(!exposed)continue;if(output[exposed])throw new Error(`Duplicate model: ${exposed}`);const entry:ModelEntry={};if(row.upstream.trim())entry.upstream_model=row.upstream.trim();if(row.info)entry.model_info=copyInfo(row.info);output[exposed]=entry;}if(!Object.keys(output).length)throw new Error('Add at least one model.');return output;}
  async function save():Promise<void>{if(!name.trim()||!provider){error='Group name and provider are required.';return;}busy=true;error='';try{const body:Record<string,unknown>={provider,type:'llm',models:modelPayload()};if(toolProfile)body.tool_profile=toolProfile;if(originalName&&originalName!==name.trim())body.rename_from=originalName;await api.put(`/admin/api/config/model-groups/${encodeURIComponent(name.trim())}`,body);notice=`Model group ${name.trim()} saved.`;groupOpen=false;await load();}catch(cause){error=message(cause);}finally{busy=false;}}
  async function remove(groupName:string):Promise<void>{if(!confirm(`Delete model group “${groupName}”?`))return;busy=true;error='';try{await api.del(`/admin/api/config/model-groups/${encodeURIComponent(groupName)}`);await load();notice=`Model group ${groupName} deleted.`;}catch(cause){error=message(cause);}finally{busy=false;}}
  async function discover():Promise<void>{if(!provider)return;busy=true;error='';discovered=[];selectedDiscovered=new Set();try{const result=await api.get<{models?:string[];error?:string}>(`/admin/api/config/providers/${encodeURIComponent(provider)}/models`);if(result.error)throw new Error(result.error);discovered=result.models??[];}catch(cause){error=message(cause);}finally{busy=false;}}
  function selectModel(model:string,checked:boolean):void{const next=new Set(selectedDiscovered);checked?next.add(model):next.delete(model);selectedDiscovered=next;}function addSelected():void{const existing=new Set(rows.map((row)=>row.name));for(const upstream of discovered)if(selectedDiscovered.has(upstream)){const exposed=`${prefix}${upstream}`;if(!existing.has(exposed)){addRow(exposed,{upstream_model:prefix?upstream:undefined});existing.add(exposed);}}selectedDiscovered=new Set();fetchOpen=false;groupOpen=true;}
  function openFetch():void{reset();fetchOpen=true;}function toggleGroup(groupName:string):void{const next=new Set(collapsed);next.has(groupName)?next.delete(groupName):next.add(groupName);collapsed=next;}function visibleGroup(groupName:string,group:Group):boolean{if(providerFilter&&group.provider!==providerFilter)return false;const query=search.trim().toLowerCase();return!query||[groupName,group.provider,...Object.keys(group.models??{})].some((item)=>String(item??'').toLowerCase().includes(query));}
  async function saveTaskModels():Promise<void>{busy=true;error='';try{await api.put('/admin/api/config/codex',{auto_review_model_override:reviewModel||null,memories:{consolidation_model:consolidationModel||null,extract_model:extractModel||null}});notice='Codex task models saved.';await load();}catch(cause){error=message(cause);}finally{busy=false;}}
  onMount(()=>{reset();const controller=new AbortController();void load(controller.signal);return()=>controller.abort();});
</script>
<div class="section"><div class="section-header"><h2>{t('section.codexTaskModels','Codex Task Models')}</h2></div><div class="codex-task-model-grid"><div class="codex-task-model-field"><label for="autoReviewModel">{t('label.autoApprovalModel','Automatic approval (default codex-auto-review)')}</label><select id="autoReviewModel" bind:value={reviewModel} onchange={()=>void saveTaskModels()}><option value="">codex-auto-review (default)</option>{#each configuredModels as model}<option value={model}>{model}</option>{/each}</select></div><div class="codex-task-model-field"><label for="memoryConsolidationModel">{t('label.memoryConsolidationModel','Memory consolidation (default gpt-5.4)')}</label><select id="memoryConsolidationModel" bind:value={consolidationModel} onchange={()=>void saveTaskModels()}><option value="">gpt-5.4 (default)</option>{#each configuredModels as model}<option value={model}>{model}</option>{/each}</select></div><div class="codex-task-model-field"><label for="memoryExtractModel">{t('label.memoryExtractModel','Memory extraction (default gpt-5.4-mini)')}</label><select id="memoryExtractModel" bind:value={extractModel} onchange={()=>void saveTaskModels()}><option value="">gpt-5.4-mini (default)</option>{#each configuredModels as model}<option value={model}>{model}</option>{/each}</select></div></div></div>
<div class="section"><div class="section-header"><h2>{t('section.models','Model Routing')}</h2><div style="display:flex;gap:6px"><button class="btn btn-sm" onclick={openFetch}>{t('btn.fetchModels','⬇ Fetch from Provider')}</button><button class="btn btn-sm" onclick={openNew}>{t('btn.addModelGroup','+ Add Model Group')}</button></div></div>{#if error}<div class="toast error show" role="alert">{error}</div>{/if}{#if notice}<div class="toast show" role="status">{notice}</div>{/if}<div class="model-toolbar"><select aria-label="Provider filter" bind:value={providerFilter}><option value="">All Providers</option>{#each Object.keys(config.providers??{}) as item}<option value={item}>{item}</option>{/each}</select><input aria-label="Search models" bind:value={search} placeholder="Search models..." /><span class="model-count">{Object.keys(config.models??{}).length} models</span></div>
{#if loading}<p style="color:var(--text-dim)">Loading model groups...</p>{:else}<div class="model-group-list">{#each Object.entries(config.model_groups??{}) as [groupName,group]}{#if visibleGroup(groupName,group)}<div class="model-group-card" class:collapsed={collapsed.has(groupName)} class:config-error={!!group.validation_error}><div class="model-group-head"><div class="model-group-title"><button class="key-btn model-group-toggle" aria-label="Toggle group" onclick={()=>toggleGroup(groupName)}>{collapsed.has(groupName)?'▸':'▾'}</button><code>{groupName}</code>{#if group.validation_error}<span class="badge badge-error" title={group.validation_error}>Config Error</span>{/if}<span class="model-group-meta">{[group.type??'llm',group.provider??'',...(group.tool_profile?[group.tool_profile]:[]),`${Object.keys(group.models??{}).length}`].join(' · ')}</span></div><div class="model-group-actions"><button class="btn btn-sm" onclick={()=>edit(groupName,group)}>Edit</button><button class="btn btn-sm btn-danger" disabled={busy} onclick={()=>void remove(groupName)}>Delete</button></div></div><div class="model-group-body"><div class="table-scroll"><table><tbody>{#each Object.entries(group.models??{}) as [modelName,entry]}<tr style:opacity={config.providers?.[group.provider??'']?.enabled===false?0.4:1}><td><code>{modelName}</code>{#if entry.upstream_model}<span style="font-size:11px;color:var(--text-dim)"> → {entry.upstream_model}</span>{/if}{#each entry.model_info?.input_modalities??[] as modality}<span class="badge badge-cap">{modality}</span>{/each}</td><td>{group.provider??''}</td><td style="text-align:right"><ModelTestPanel model={modelName}/></td></tr>{/each}</tbody></table></div></div></div>{/if}{:else}<div style="color:var(--text-dim);font-size:13px">No model groups configured.</div>{/each}</div>{/if}</div>

<Modal open={groupOpen} labelledby="model-group-title" wide onclose={()=>{groupOpen=false;closeInfo();}}>
  {#snippet children()}
    <h3 id="model-group-title">{originalName?t('modal.editModelGroup','Edit Model Group'):t('modal.addModelGroup','Add Model Group')}</h3>
    <div class="form-group"><label for="modelGroupName">{t('label.modelGroupName','Model Group Name')}</label><input id="modelGroupName" bind:value={name} placeholder="e.g. OpenAI Production" /></div>
    <div class="form-group"><label for="modelGroupProvider">{t('label.provider','Provider')}</label><select id="modelGroupProvider" bind:value={provider}>{#each Object.keys(config.providers??{}) as item}<option value={item}>{item}</option>{/each}</select></div>
    <div class="form-group"><label for="modelGroupToolProfile">{t('tools.profile','Profile')}</label><select id="modelGroupToolProfile" bind:value={toolProfile}><option value="">Provider default</option>{#each config.tool_profile_presets??[] as profile}<option value={profile.id}>{profile.name}</option>{/each}</select></div>
    <div class="form-group"><div class="form-label">{t('label.modelMappings','Model Mappings')}</div><div>{#each rows as row(row.id)}{@const status=infoStatus(row)}<div class="model-group-row"><input aria-label="Exposed model" bind:value={row.name} placeholder="exposed model name" /><input aria-label="Upstream model" bind:value={row.upstream} placeholder="upstream model (optional)" /><div><div class="model-preset-status" class:detected={status.detected} class:modified={status.modified}>{status.text}</div><div class="model-row-controls"><button class="btn btn-sm" onclick={()=>editInfo(row)}>{t('modelInfo.manual','Enter Model Information Manually')}</button><button class="btn btn-sm btn-danger" onclick={()=>removeRow(row.id)}>{t('btn.remove','Remove')}</button></div></div></div>{/each}</div><button class="btn btn-sm" onclick={()=>addRow()}>{t('btn.addMapping','+ Add Mapping')}</button></div>
    <div class="modal-actions"><button class="btn" onclick={()=>{groupOpen=false;closeInfo();}}>{t('btn.cancel','Cancel')}</button><button class="btn btn-primary" disabled={busy} onclick={()=>void save()}>{t('btn.save','Save')}</button></div>
  {/snippet}
  {#snippet sidecar()}
    <div class="modal model-info-modal" class:open={infoRowId!==null&&infoDraft!==null} role="dialog" aria-modal="true" aria-labelledby="model-info-title">
      {#if infoDraft}
        <h3 id="model-info-title">{t('modelInfo.title','Model Information')}</h3>
        <div class="model-info-grid">
          <div class="form-group span-2"><label for="modelInfoSlug">{t('modelInfo.slug','Slug')}</label><input id="modelInfoSlug" bind:value={infoDraft.slug}/></div>
          <div class="form-group"><label for="modelInfoDisplayName">{t('modelInfo.displayName','Display Name')}</label><input id="modelInfoDisplayName" bind:value={infoDraft.display_name}/></div>
          <div class="form-group"><label for="modelInfoIdentity">{t('modelInfo.identity','Identity')}</label><input id="modelInfoIdentity" bind:value={infoDraft.identity}/></div>
          <div class="form-group span-2"><label for="modelInfoDescription">{t('modelInfo.description','Description')}</label><textarea id="modelInfoDescription" bind:value={infoDraft.description}></textarea></div>
          <div class="form-group"><label for="modelInfoPriority">{t('modelInfo.priority','Priority')}</label><input id="modelInfoPriority" type="number" min="1" bind:value={infoDraft.priority}/></div>
          <div class="form-group"><label for="modelInfoContextWindow">{t('modelInfo.contextWindow','Context Window')}</label><input id="modelInfoContextWindow" type="number" min="1" bind:value={infoDraft.context_window}/></div>
          <div class="form-group span-2"><div class="form-label">{t('modelInfo.modalities','Input Modalities')}</div><div class="checkbox-group model-info-checkbox-group">{#each ['text','image'] as value}<label><input type="checkbox" checked={infoDraft.input_modalities.includes(value)} onchange={(event)=>toggleList('input_modalities',value,event.currentTarget.checked)}/>{value}</label>{/each}</div></div>
          <div class="form-group span-2"><div class="form-label">{t('modelInfo.reasoningLevels','Supported Reasoning Levels')}</div><div class="checkbox-group model-info-checkbox-group">{#each ['low','medium','high','xhigh','max','ultra'] as value}<label><input type="checkbox" checked={infoDraft.supported_reasoning_levels.includes(value)} onchange={(event)=>toggleList('supported_reasoning_levels',value,event.currentTarget.checked)}/>{value}</label>{/each}</div></div>
        </div>
        <div class="modal-actions"><button class="btn" type="button" onclick={clearInfo}>{#if infoRow()&&presetFor(infoRow()!)}{format(t('modelInfo.restorePreset','Restore {display_name} preset'),presetFor(infoRow()!)!.display_name)}{:else}{t('modelInfo.useAutomatic','Use Automatic Detection')}{/if}</button><button class="btn" type="button" onclick={closeInfo}>{t('btn.cancel','Cancel')}</button><button class="btn btn-primary" type="button" onclick={applyInfo}>{t('btn.applyChanges','Apply Changes')}</button></div>
      {/if}
    </div>
  {/snippet}
</Modal>
<Modal open={fetchOpen} labelledby="fetch-models-title" wide onclose={()=>fetchOpen=false}><h3 id="fetch-models-title">Fetch Models from Provider</h3><div class="form-group"><label for="fetchProvider">Select Provider</label><select id="fetchProvider" bind:value={provider}>{#each Object.keys(config.providers??{}) as item}<option value={item}>{item}</option>{/each}</select></div><div class="form-group"><label for="fetchGroupName">Model Group Name</label><input id="fetchGroupName" bind:value={name} placeholder="New model group name" /></div>{#if discovered.length}<div class="fetch-toolbar"><input bind:value={discoveryFilter} placeholder="Filter models..."/><button class="btn btn-sm" onclick={()=>selectedDiscovered=new Set(filteredDiscovered)}>Select All</button><button class="btn btn-sm" onclick={()=>selectedDiscovered=new Set()}>Deselect All</button><span class="fetch-count">{selectedDiscovered.size} selected</span></div><div class="fetch-models-list">{#each filteredDiscovered as model}<label><input type="checkbox" checked={selectedDiscovered.has(model)} onchange={(event)=>selectModel(model,event.currentTarget.checked)}/>{model}</label>{/each}</div><div class="prefix-group"><label for="fetchPrefix">Prefix:</label><input id="fetchPrefix" bind:value={prefix} placeholder="e.g. myprefix/"/></div>{/if}<div class="modal-actions"><button class="btn" onclick={()=>fetchOpen=false}>Cancel</button>{#if !discovered.length}<button class="btn btn-primary" disabled={busy||!provider} onclick={()=>void discover()}>Fetch</button>{:else}<button class="btn btn-primary" disabled={!selectedDiscovered.size||!name.trim()} onclick={addSelected}>Apply Changes</button>{/if}</div></Modal>
